// Sound for the prototypes: the nature-documentary foley generated by
// micro/design/source/build_audio.py (listed in audio-list.js). Ids are
// "<prototype>/<name>", e.g. 'mite/step'. A sound with several takes plays a
// random one each time. Missing files are silent, never an error.
//
//   const audio = createAudio(['mite/amb-moss', 'mite/step', 'mite/dash']);
//   audio.addToFeatures(features);           // Sound and Ambience switches
//   const amb = audio.loop('mite/amb-moss');  // starts once audio is unlocked
//   audio.play('mite/step', { volume: 0.5, rate: 1 + Math.random() * 0.1 });
//   amb.set({ volume: 0.4 });                 // ramps smoothly
//
// Browsers only allow sound after a user gesture; the first key, click, touch
// or controller button unlocks it (the pad is polled by the prototype, so call
// audio.unlock() when any pad button is pressed).
import { SOUNDS } from './audio-list.js';

const base = new URL('../', import.meta.url);

export function createAudio(ids = Object.keys(SOUNDS)) {
  let ctx = null, master = null, ambBus = null, sfxBus = null;
  let enabled = true, ambience = true;
  const buffers = new Map(); // id -> Promise<AudioBuffer[]>
  const loops = new Set();

  function ensure() {
    if (ctx) return ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = enabled && !(document.hidden || !document.hasFocus()) ? 0.9 : 0;
    master.connect(ctx.destination);
    sfxBus = ctx.createGain(); sfxBus.connect(master);
    ambBus = ctx.createGain(); ambBus.gain.value = ambience ? 1 : 0; ambBus.connect(master);
    for (const id of ids) load(id);
    for (const l of loops) l._start();
    return ctx;
  }

  function load(id) {
    if (buffers.has(id)) return buffers.get(id);
    const entry = SOUNDS[id];
    const files = entry ? entry.files : [];
    const p = Promise.all(files.map((f) => fetch(new URL(f, base)).then((r) => {
      if (!r.ok) throw new Error(`${r.status} ${f}`);
      return r.arrayBuffer();
    }).then((b) => ctx.decodeAudioData(b)).catch((e) => {
      console.error(`[micro] sound ${id} failed to load: ${e.message}`);
      return null;
    }))).then((list) => list.filter(Boolean));
    buffers.set(id, p);
    return p;
  }

  const unlock = () => {
    if (!ensure()) return;
    if (ctx.state === 'suspended' && !(document.hidden || !document.hasFocus())) ctx.resume().catch(() => {});
  };
  for (const ev of ['keydown', 'pointerdown', 'touchstart']) addEventListener(ev, unlock, { passive: true });

  // Silent whenever the tab is hidden or the window loses focus; back on return.
  let away = document.hidden || !document.hasFocus();
  const updateAway = () => {
    away = document.hidden || !document.hasFocus();
    if (!master) return;
    master.gain.setTargetAtTime(enabled && !away ? 0.9 : 0, ctx.currentTime, 0.05);
    if (away && ctx.state === 'running') ctx.suspend().catch(() => {});
    else if (!away && ctx.state === 'suspended') ctx.resume().catch(() => {});
  };
  document.addEventListener('visibilitychange', updateAway);
  addEventListener('blur', updateAway);
  addEventListener('focus', updateAway);
  addEventListener('pagehide', updateAway);

  const api = {
    /** Call when a controller button is pressed (gamepads don't fire DOM events). */
    unlock,
    get ready() { return !!ctx && ctx.state === 'running'; },
    /** Play a one-shot. Returns nothing; silent if not loaded or disabled. */
    play(id, { volume = 1, rate = 1, pan = 0, delay = 0 } = {}) {
      if (!ctx || !enabled || ctx.state !== 'running') return;
      const v = (SOUNDS[id]?.volume ?? 1) * volume;
      load(id).then((list) => {
        if (!list.length) return;
        const src = ctx.createBufferSource();
        src.buffer = list[(Math.random() * list.length) | 0];
        src.playbackRate.value = rate;
        const g = ctx.createGain(); g.gain.value = v;
        let node = src.connect(g);
        if (pan && ctx.createStereoPanner) { const p = ctx.createStereoPanner(); p.pan.value = Math.max(-1, Math.min(1, pan)); node = node.connect(p); }
        node.connect(sfxBus);
        src.start(ctx.currentTime + delay);
      });
    },
    /**
     * A looping sound (ambience or a continuous layer such as the cilia beat).
     * Ids starting with 'amb' go through the Ambience switch.
     * Returns { set({volume, rate}), stop() }.
     */
    loop(id, { volume = 1, rate = 1 } = {}) {
      const isAmb = id.split('/')[1]?.startsWith('amb');
      const state = { volume, rate, src: null, gain: null, stopped: false };
      const handle = {
        _start() {
          if (!ctx || state.src || state.stopped) return;
          load(id).then((list) => {
            if (!list.length || state.src || state.stopped) return;
            const src = ctx.createBufferSource();
            src.buffer = list[0]; src.loop = true; src.playbackRate.value = state.rate;
            const g = ctx.createGain(); g.gain.value = 0;
            g.gain.setTargetAtTime((SOUNDS[id]?.volume ?? 1) * state.volume, ctx.currentTime, 0.4);
            src.connect(g).connect(isAmb ? ambBus : sfxBus);
            src.start();
            state.src = src; state.gain = g;
          });
        },
        set({ volume: v, rate: r } = {}) {
          if (v !== undefined) state.volume = v;
          if (r !== undefined) state.rate = r;
          if (state.gain) state.gain.gain.setTargetAtTime((SOUNDS[id]?.volume ?? 1) * state.volume, ctx.currentTime, 0.08);
          if (state.src) state.src.playbackRate.setTargetAtTime(state.rate, ctx.currentTime, 0.08);
        },
        stop() {
          state.stopped = true; loops.delete(handle);
          if (state.gain) state.gain.gain.setTargetAtTime(0, ctx.currentTime, 0.2);
          if (state.src) state.src.stop(ctx.currentTime + 1);
        },
      };
      loops.add(handle);
      handle._start();
      return handle;
    },
    /** Register Sound and Ambience switches in the feature panel. */
    addToFeatures(features) {
      features.add({ id: 'sound', group: 'Controls', label: 'Sound effects',
        about: 'Nature-documentary foley generated with ElevenLabs (micro/design/sound-effects.md). Nothing is audible at these scales; these are what a wildlife film would put on the scene.',
        on: true, onChange: (v) => { enabled = v; if (master) master.gain.setTargetAtTime(v && !away ? 0.9 : 0, ctx.currentTime, 0.05); } });
      features.add({ id: 'ambience', group: 'Controls', label: 'Ambience',
        about: 'The looping background bed of the habitat.',
        on: true, onChange: (v) => { ambience = v; if (ambBus) ambBus.gain.setTargetAtTime(v ? 1 : 0, ctx.currentTime, 0.2); } });
    },
  };
  return api;
}
